export interface Recipient {
  name: string;
  postalAddress: string;
}

export interface ProviderRequest {
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}

export interface ShippingDependencies {
  repository: {
    get(shipmentId: string): Promise<unknown>;
    save(shipmentId: string, record: unknown): Promise<void>;
  };
  atlas: {
    book(request: ProviderRequest): Promise<unknown>;
  };
  beacon: {
    reserve(request: ProviderRequest): Promise<unknown>;
  };
  logger: {
    info(event: Record<string, unknown>): void;
  };
}

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type AbortClassification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";

interface Rejection {
  provider: Provider;
  reason: RefusalReason;
}

interface ShipmentFields {
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}

interface QueuedShipment extends ShipmentFields {
  state: "queued";
}

interface DispatchedShipment extends ShipmentFields {
  state: "dispatched";
  provider: Provider;
  bookingId: string;
  dispatchedAtMs: number;
}

interface DeferredShipment extends ShipmentFields {
  state: "deferred";
  nextProvider: Provider;
  retryAtMs: number;
  rejections: Rejection[];
}

interface UnavailableShipment extends ShipmentFields {
  state: "unavailable";
  rejections: Rejection[];
}

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

interface AbortBody {
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: Provider | "repository";
  classification: AbortClassification;
  rejections: Rejection[];
}

export interface ServiceResponse {
  status: number;
  body:
    | PublicShipment
    | AbortBody
    | {
        code: "invalid_command" | "not_found";
      };
}

type Command =
  | { op: "get"; shipmentId: string }
  | { op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient };

type CarrierOutcome =
  | { kind: "confirmed"; bookingId: string }
  | { kind: "refused"; reason: RefusalReason }
  | { kind: "throttled"; retryAtMs: number }
  | { kind: "aborted"; classification: "unknown_failure" | "invalid_provider_response" };

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isAllowedReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || typeof value.shipmentId !== "string" || value.shipmentId.length === 0) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    typeof value.nowMs !== "number" ||
    !Number.isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function publicRejections(rejections: Rejection[]): Rejection[] {
  return rejections.map((rejection) => ({
    provider: rejection.provider,
    reason: rejection.reason,
  }));
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  if (shipment.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (shipment.state === "dispatched") {
    return {
      ...fields,
      state: "dispatched",
      provider: shipment.provider,
      bookingId: shipment.bookingId,
      dispatchedAtMs: shipment.dispatchedAtMs,
    };
  }
  if (shipment.state === "deferred") {
    return {
      ...fields,
      state: "deferred",
      nextProvider: shipment.nextProvider,
      retryAtMs: shipment.retryAtMs,
      rejections: publicRejections(shipment.rejections),
    };
  }
  return {
    ...fields,
    state: "unavailable",
    rejections: publicRejections(shipment.rejections),
  };
}

function abortBody(
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: AbortClassification,
  rejections: Rejection[],
): AbortBody {
  return {
    code: "dispatch_aborted",
    shipmentId,
    failedAt,
    classification,
    rejections: publicRejections(rejections),
  };
}

function classifyAtlasRejection(value: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(value) || typeof value.code !== "string") {
    return { kind: "aborted", classification: "unknown_failure" };
  }
  if (value.code === "cannot_ship") {
    if (isAllowedReason(value.reason)) {
      return { kind: "refused", reason: value.reason };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (value.code === "rate_limited") {
    if (
      typeof value.retryAtMs === "number" &&
      Number.isSafeInteger(value.retryAtMs) &&
      value.retryAtMs > nowMs
    ) {
      return { kind: "throttled", retryAtMs: value.retryAtMs };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", classification: "unknown_failure" };
}

function classifyBeaconRejection(value: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(value) || typeof value.type !== "string") {
    return { kind: "aborted", classification: "unknown_failure" };
  }
  if (value.type === "rejected") {
    if (isObject(value.details) && isAllowedReason(value.details.reason)) {
      return { kind: "refused", reason: value.details.reason };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (value.type === "throttled") {
    if (
      isObject(value.details) &&
      typeof value.details.retryAtMs === "number" &&
      Number.isSafeInteger(value.details.retryAtMs) &&
      value.details.retryAtMs > nowMs
    ) {
      return { kind: "throttled", retryAtMs: value.details.retryAtMs };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", classification: "unknown_failure" };
}

function classifyConfirmation(provider: Provider, value: unknown): CarrierOutcome {
  if (provider === "atlas") {
    if (isObject(value) && typeof value.bookingId === "string" && value.bookingId.length > 0) {
      return { kind: "confirmed", bookingId: value.bookingId };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (isObject(value) && typeof value.reference === "string" && value.reference.length > 0) {
    return { kind: "confirmed", bookingId: value.reference };
  }
  return { kind: "aborted", classification: "invalid_provider_response" };
}

async function callCarrier(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<CarrierOutcome> {
  try {
    const value =
      provider === "atlas"
        ? await dependencies.atlas.book(request)
        : await dependencies.beacon.reserve(request);
    return classifyConfirmation(provider, value);
  } catch (error) {
    return provider === "atlas"
      ? classifyAtlasRejection(error, nowMs)
      : classifyBeaconRejection(error, nowMs);
  }
}

function hasRefusal(rejections: Rejection[], provider: Provider): boolean {
  return rejections.some((rejection) => rejection.provider === provider);
}

export function createShippingService(dependencies: ShippingDependencies) {
  function emitAbort(body: AbortBody): void {
    dependencies.logger.info({
      shipmentId: body.shipmentId,
      action: "aborted",
      failedAt: body.failedAt,
      classification: body.classification,
      rejections: publicRejections(body.rejections),
    });
  }

  async function saveDecision(
    shipmentId: string,
    record: StoredShipment,
    event: Record<string, unknown>,
    responseStatus: number,
    saveFailureRejections: Rejection[],
  ): Promise<ServiceResponse> {
    try {
      await dependencies.repository.save(shipmentId, record);
    } catch {
      const body = abortBody(
        shipmentId,
        "repository",
        "repository_failure",
        saveFailureRejections,
      );
      emitAbort(body);
      return { status: 500, body };
    }
    dependencies.logger.info(event);
    return { status: responseStatus, body: publicShipment(record) };
  }

  async function abortInvocation(
    shipmentId: string,
    failedAt: Provider | "repository",
    classification: AbortClassification,
    rejections: Rejection[],
  ): Promise<ServiceResponse> {
    const body = abortBody(shipmentId, failedAt, classification, rejections);
    emitAbort(body);
    return { status: 500, body };
  }

  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      return abortInvocation(command.shipmentId, "repository", "repository_failure", []);
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    // Storage contains the host's queued records or this service's own saved JSON.
    const shipment = value as StoredShipment;
    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "dispatched") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "unavailable") {
      return { status: 422, body: publicShipment(shipment) };
    }
    if (shipment.state === "deferred" && command.nowMs < shipment.retryAtMs) {
      return { status: 202, body: publicShipment(shipment) };
    }

    const request: ProviderRequest = {
      shipmentId: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      recipient: {
        name: command.recipient.name,
        postalAddress: command.recipient.postalAddress,
      },
      idempotencyKey: shipment.id,
    };
    let nextProvider: Provider = shipment.state === "deferred" ? shipment.nextProvider : "atlas";
    const rejections =
      shipment.state === "deferred" ? publicRejections(shipment.rejections) : [];
    const attempted = new Set<Provider>();

    while (!attempted.has(nextProvider) && !hasRefusal(rejections, nextProvider)) {
      const provider = nextProvider;
      attempted.add(provider);
      const outcome = await callCarrier(dependencies, provider, request, command.nowMs);

      if (outcome.kind === "confirmed") {
        const dispatched: DispatchedShipment = {
          schemaVersion: 1,
          id: shipment.id,
          routeCode: shipment.routeCode,
          parcelGrams: shipment.parcelGrams,
          state: "dispatched",
          provider,
          bookingId: outcome.bookingId,
          dispatchedAtMs: command.nowMs,
        };
        return saveDecision(
          shipment.id,
          dispatched,
          {
            shipmentId: shipment.id,
            action: "dispatched",
            provider,
          },
          200,
          rejections,
        );
      }

      if (outcome.kind === "throttled") {
        const deferred: DeferredShipment = {
          schemaVersion: 1,
          id: shipment.id,
          routeCode: shipment.routeCode,
          parcelGrams: shipment.parcelGrams,
          state: "deferred",
          nextProvider: provider,
          retryAtMs: outcome.retryAtMs,
          rejections: publicRejections(rejections),
        };
        return saveDecision(
          shipment.id,
          deferred,
          {
            shipmentId: shipment.id,
            action: "deferred",
            provider,
            retryAtMs: outcome.retryAtMs,
            rejections: publicRejections(rejections),
          },
          202,
          rejections,
        );
      }

      if (outcome.kind === "aborted") {
        return abortInvocation(shipment.id, provider, outcome.classification, rejections);
      }

      rejections.push({ provider, reason: outcome.reason });
      if (provider === "atlas" && !hasRefusal(rejections, "beacon")) {
        nextProvider = "beacon";
        continue;
      }

      const unavailable: UnavailableShipment = {
        schemaVersion: 1,
        id: shipment.id,
        routeCode: shipment.routeCode,
        parcelGrams: shipment.parcelGrams,
        state: "unavailable",
        rejections: publicRejections(rejections),
      };
      return saveDecision(
        shipment.id,
        unavailable,
        {
          shipmentId: shipment.id,
          action: "unavailable",
          rejections: publicRejections(rejections),
        },
        422,
        rejections,
      );
    }

    const unavailable: UnavailableShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "unavailable",
      rejections: publicRejections(rejections),
    };
    return saveDecision(
      shipment.id,
      unavailable,
      {
        shipmentId: shipment.id,
        action: "unavailable",
        rejections: publicRejections(rejections),
      },
      422,
      rejections,
    );
  }

  return { handle };
}
